description:
Define a `User` interface with fields `id: number`, `name: string`, `email: string`, and `role: 'admin' | 'user'`.

Then implement `createUser(data: Omit<User, 'id'>): User` that assigns an auto-incrementing `id` starting at 1.

**Example:**
```ts
const u1 = createUser({ name: 'Alice', email: 'a@x.com', role: 'admin' });
// { id: 1, name: 'Alice', email: 'a@x.com', role: 'admin' }
const u2 = createUser({ name: 'Bob', email: 'b@x.com', role: 'user' });
// { id: 2, ... }
```

starter_code:
export interface User {
  // your fields here
}

let nextId = 1;

export function createUser(data: Omit<User, 'id'>): User {
  // your code here
}

test_suite:
test('createUser returns object with numeric id', () => {
  const u = createUser({ name: 'Alice', email: 'a@x.com', role: 'admin' });
  expect(typeof u.id).toBe('number');
});

test('id increments with each call', () => {
  const a = createUser({ name: 'A', email: 'a@x.com', role: 'user' });
  const b = createUser({ name: 'B', email: 'b@x.com', role: 'user' });
  expect(b.id).toBe(a.id + 1);
});

test('role is literal union type at runtime', () => {
  const u = createUser({ name: 'C', email: 'c@x.com', role: 'admin' });
  expect(['admin', 'user']).toContain(u.role);
});

test('all fields are preserved', () => {
  const u = createUser({ name: 'Diana', email: 'd@x.com', role: 'user' });
  expect(u.name).toBe('Diana');
  expect(u.email).toBe('d@x.com');
});

// __hidden__
test('role admin is preserved', () => {
  const u = createUser({ name: 'Eve', email: 'e@x.com', role: 'admin' });
  expect(u.role).toBe('admin');
});

solution:
export interface User {
  id: number;
  name: string;
  email: string;
  role: 'admin' | 'user';
}

let nextId = 1;

export function createUser(data: Omit<User, 'id'>): User {
  return { id: nextId++, ...data };
}
